## Patterns to follow

**The union — server (`src/server/agent-requests.ts`), write exactly this:**
```ts
/** Requests nobody acked are dropped after a day. */
export const AGENT_REQUEST_TTL_MS = 24 * 60 * 60 * 1000;
/** `refresh` requests are never acked: every tab acts on them, and they expire after 10 s. */
export const REFRESH_TTL_MS = 10_000;

export interface StartRunPrefill {
  /** Workspace-relative, `/` separators. */
  tasksDir: string;
  /** Workspace-relative, `/` separators. */
  spec: string;
  provider?: string;
  options?: RunOptionsBody;
}

/** Fields every agent request has. */
interface AgentRequestBase {
  id: string;
  workspaceId: string;
  /** The terminal's agent id when known (e.g. "claude"). */
  agent?: string;
  /** The terminal's title, for the toast. */
  terminalTitle?: string;
  createdAt: string;
}

/** A request from one terminal: acted on where that terminal is on screen (else from a toast), then acked. */
interface TerminalRequestBase extends AgentRequestBase {
  terminalId: string;
}

/** `open_start_run`: open the Start run drawer, prefilled. */
export interface StartRunRequest extends TerminalRequestBase {
  kind: "start-run";
  prefill: StartRunPrefill;
}
/** `open_run`: show a run (run pane on the Terminals page, else the run page). */
export interface OpenRunRequest extends TerminalRequestBase {
  kind: "open-run";
  runId: string;
}
/** `open_graph`: exactly one of `runId` / `tasksDir` (workspace-relative); `node` to focus. */
export interface OpenGraphRequest extends TerminalRequestBase {
  kind: "open-graph";
  runId?: string;
  tasksDir?: string;
  node?: string;
}
/** `propose_graph`: preview a task folder's graph with Approve / Reject; Approve opens Start run with `prefill`. */
export interface ProposeGraphRequest extends TerminalRequestBase {
  kind: "propose-graph";
  prefill: StartRunPrefill;
}
/** `refresh_ui`: every open tab re-fetches its data. No terminal; never acked; expires after REFRESH_TTL_MS. */
export interface RefreshRequest extends AgentRequestBase {
  kind: "refresh";
}

export type AgentRequest = StartRunRequest | OpenRunRequest | OpenGraphRequest | ProposeGraphRequest | RefreshRequest;
export type AgentRequestKind = AgentRequest["kind"];
/** What `add` takes: a request without `id` and `createdAt` (distributes over the union). */
export type NewAgentRequest<R extends AgentRequest = AgentRequest> = R extends AgentRequest ? Omit<R, "id" | "createdAt"> : never;
```

**The queue methods:**
```ts
export class AgentRequests {
  private readonly items: AgentRequest[] = [];
  constructor(private readonly now: () => number = Date.now) {}

  /** Queues a request; it replaces a pending one of the same terminal and kind. `refresh` never replaces one. */
  add(r: NewAgentRequest): AgentRequest {
    if (r.kind !== "refresh") {
      const i = this.items.findIndex((x) => x.kind === r.kind && x.kind !== "refresh" && x.terminalId === r.terminalId);
      if (i >= 0) this.items.splice(i, 1);
    }
    const req = { ...r, id: randomUUID(), createdAt: new Date(this.now()).toISOString() } as AgentRequest;
    this.items.push(req);
    return req;
  }

  /** The pending requests, oldest first, without expired ones (refresh: 10 s, others: a day). */
  list(): AgentRequest[] { /* same loop as today, cutoff per item: kind === "refresh" ? REFRESH_TTL_MS : AGENT_REQUEST_TTL_MS */ }

  /** A pending request by id (expired ones are gone), or undefined. */
  get(id: string): AgentRequest | undefined { return this.list().find((x) => x.id === id); }

  /** Removes a request; false when it is not pending or is a `refresh` request. */
  ack(id: string): boolean { /* as today, plus: if the found item's kind is "refresh" return false without removing */ }
}
```

**The union — web (`src/web/types.ts`, replace lines 202–211), the same shape:**
```ts
/** What an agent's start-run / propose-graph request fills into the Start run drawer. */
export interface AgentRequestPrefill {
  tasksDir: string;
  spec: string;
  provider?: string;
  options?: Record<string, unknown>;
}
interface AgentRequestBase {
  id: string;
  workspaceId: string;
  agent?: string;
  terminalTitle?: string;
  createdAt: string;
}
export interface StartRunRequest extends AgentRequestBase { kind: "start-run"; terminalId: string; prefill: AgentRequestPrefill }
export interface OpenRunRequest extends AgentRequestBase { kind: "open-run"; terminalId: string; runId: string }
export interface OpenGraphRequest extends AgentRequestBase { kind: "open-graph"; terminalId: string; runId?: string; tasksDir?: string; node?: string }
export interface ProposeGraphRequest extends AgentRequestBase { kind: "propose-graph"; terminalId: string; prefill: AgentRequestPrefill }
export interface RefreshRequest extends AgentRequestBase { kind: "refresh" }
export type AgentRequest = StartRunRequest | OpenRunRequest | OpenGraphRequest | ProposeGraphRequest | RefreshRequest;
/** The requests tied to a terminal (all but refresh). */
export type TerminalAgentRequest = Exclude<AgentRequest, RefreshRequest>;
```

**Tool pattern** (mirror `tools/open-start-run.ts`):
```ts
// `open_run` (docs/prd/agent-supervisor.md): queues a request for the browser to show a run.
import { z } from "zod";
import { isToolResult, requireWorkspace, runDirOrError } from "./run-helpers.js";
import { defineTool } from "./types.js";

export const openRun = defineTool({
  name: "open_run",
  description: "Show a run of this workspace on the user's screen in graph-manager: in a pane next to this terminal when it is on screen, else as a notification that opens the run page. Returns at once.",
  input: z.object({ runId: z.string().min(1).describe("The run id, e.g. gm-20261109-101500-ab12") }),
  async run(i, tc) {
    const ws = requireWorkspace(tc);
    if (isToolResult(ws)) return ws;
    const dir = await runDirOrError(ws, i.runId);
    if (isToolResult(dir)) return dir;
    tc.ctx.agentRequests.add({ kind: "open-run", terminalId: tc.terminal.id, workspaceId: ws.id, agent: tc.terminal.agent, terminalTitle: tc.terminal.title, runId: i.runId });
    return { text: `Opened run ${i.runId} in graph-manager.` };
  },
});
```

**Toast with an in-app link and an ack** (`ToastAction` in `web/ui/toast.tsx`):
```ts
toastRef.current.show({ tone: "live", text: requestText(r), action: { label: "Open", to: `/runs/${encodeURIComponent(r.workspaceId)}/${encodeURIComponent(r.runId)}`, onClick: () => ack(r.id) } });
```

**Server test pattern:** copy `beforeEach`/`afterEach`/`call`/`requests` from `src/server/tools/open-start-run.test.ts` lines 1–60 (change the URL to `/api/internal/tools/open_run` etc.). A run folder is just a directory: `await mkdir(path.join(wsDir, ".graph-execution", RUN), { recursive: true })` with `const RUN = "gm-20261109-101500-ab12"`. Wrap the suite in `describe.skipIf(process.platform === "win32")` like that file (terminals need a PTY).

**Web test pattern:** `src/web/agentRequests.test.tsx` — `serve([...])` stubs `fetch`, `renderHost(visible)` renders `MemoryRouter > ToastProvider > OverviewProvider > VisibleTerminalsProvider > SetVisible + Refresh + AgentRequestHost`, `acks(f)` lists ack URLs. The `request()` factory there must become typed for one variant: `const request = (extra: Partial<StartRunRequest> = {}): StartRunRequest => ({ … })`.

